UPDATE PAYROLL_EMP SET
	PE_EMAIL = #{email}, PE_BASE = #{base,jdbcType=DOUBLE}, PE_MEAL = #{meal,jdbcType=DOUBLE},
	PE_POS = #{pos,jdbcType=DOUBLE}, PE_CAR = #{car,jdbcType=DOUBLE}
WHERE PE_WORKER_NO = #{worker_no}

