SELECT PS_IDX AS ps_idx, PS_YM AS ym, PS_WORKER_NO AS worker_no, PS_SENT_DATE AS sentDate
FROM PAYROLL_SENT WITH(NOLOCK)
WHERE PS_YM = #{value}

