UPDATE PAYROLL_SET SET
	PST_CO = #{co}, PST_FROM_EMAIL = #{fromEmail}, PST_FN = #{fn}, PST_MODE = #{mode}, PST_BCC = #{bcc},
	PST_NP = #{np,jdbcType=DOUBLE}, PST_HI = #{hi,jdbcType=DOUBLE}, PST_LT = #{lt,jdbcType=DOUBLE},
	PST_EI = #{ei,jdbcType=DOUBLE}, PST_TX = #{tx,jdbcType=DOUBLE}, PST_MEAL = #{mealLimit,jdbcType=DOUBLE},
	PST_SMTP_HOST = #{smtpHost}, PST_SMTP_PORT = #{smtpPort,jdbcType=INTEGER}, PST_SMTP_USER = #{smtpUser}, PST_SMTP_PASS = #{smtpPass}
WHERE PST_IDX = #{pst_idx}
